// Must match the Verify Token you type in Meta → WhatsApp → Configuration → Webhook.
const VERIFY_TOKEN = 'REPLACE_WITH_A_LONG_RANDOM_STRING';
const q = $json.query || {};
const ok = q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === VERIFY_TOKEN;
return [{ json: { body: ok ? String(q['hub.challenge'] || '') : 'forbidden' } }];

// Edit once. API keys and tokens live in n8n Credentials, never here.
const CONFIG = {
  MEET_WHATSAPP: '91XXXXXXXXXX',          // Meet's WhatsApp: country code + number, no +
  MEET_PHONE_E164: '+91XXXXXXXXXX',        // number Jarvis calls for urgent items
  WA_PHONE_NUMBER_ID: 'XXXXXXXXXXXXXXX',
  WA_API: 'https://graph.facebook.com/v21.0',
  SLACK_CHANNEL: 'C0AKT2RDQNA',
  TWILIO_ACCOUNT_SID: 'ACXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX',
  TWILIO_FROM: '+1XXXXXXXXXX',             // Twilio voice number
  N8N_PUBLIC_URL: 'https://n8n.YOUR-DOMAIN.com', // HTTPS address of this n8n (needed by Meta + Twilio)
  MODEL_FAST: 'claude-haiku-4-5-20251001',
  MODEL_BRAIN: 'claude-sonnet-5-5',
  // false = Maya drafts every guest reply and Meet approves it (WhatsApp "send" or by voice).
  // true  = Maya answers routine questions herself; she still escalates anything on the policy list.
  AUTO_SEND: false
};
return $input.all().map(i => ({ json: { ...i.json, CONFIG } }));

const C = $json.CONFIG;
const value = ((($json.body || {}).entry || [])[0] || {}).changes?.[0]?.value || {};
const m = (value.messages || [])[0];
if (!m) return []; // delivery/read receipts: nothing to do
const contact = (value.contacts || [])[0] || {};
let text = '';
if (m.type === 'text') text = m.text.body;
else if (m.type === 'image') text = m.image.caption || '';
else if (m.type === 'interactive') text = m.interactive.button_reply?.title || m.interactive.list_reply?.title || '';
else if (m.type === 'button') text = m.button.text;
else text = '[guest sent a ' + m.type + ' message]';
return [{ json: {
  from: m.from,
  name: contact.profile?.name || '',
  wa_msg_id: m.id,
  type: m.type,
  text,
  image_id: m.type === 'image' ? m.image.id : null,
  isMeet: m.from === C.MEET_WHATSAPP,
  hasImage: m.type === 'image'
} }];

const C = $('Config').first().json.CONFIG;
const msg = $('Read message').first().json;
const INSTR = [
  'You read a message that Meet, owner of The Empire Stays (Airbnb operator, Mumbai + Thane), sent to the automation WhatsApp number.',
  'Decide what he wants and extract details. Reply with one JSON object only:',
  '{"type":"guest_contact"|"decision"|"other",',
  ' "guest_name":string|null, "guest_phone":string|null, "confirmation_code":string|null,',
  ' "listing_name":string|null, "check_in":"YYYY-MM-DD"|null, "check_out":"YYYY-MM-DD"|null,',
  ' "decision":"approve"|"reject"|"custom"|null, "custom_reply":string|null}',
  'guest_contact = he shares a guest name and/or phone number, or a screenshot of an Airbnb reservation.',
  'guest_phone = digits only with country code, no plus; a 10-digit Indian mobile becomes 91 + number.',
  'decision = he answers a pending escalation: approve ("send", "ok", "go ahead"), reject ("hold", "don\'t send"), or custom (he dictates what to tell the guest).',
  'For custom, write custom_reply as the final guest-facing WhatsApp message in Maya\'s voice: warm, short, never robotic, English.'
].join('\n');
let content;
const it = $input.first();
if (it.binary && it.binary.data) {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  content = [
    { type: 'image', source: { type: 'base64', media_type: it.binary.data.mimeType || 'image/jpeg', data: buf.toString('base64') } },
    { type: 'text', text: INSTR + (msg.text ? '\nCaption: ' + msg.text : '') }
  ];
} else {
  content = INSTR + '\n\nMeet wrote: ' + msg.text;
}
return [{ json: { claudeRequest: { model: C.MODEL_FAST, max_tokens: 700, messages: [{ role: 'user', content }] } } }];

const txt = ($json.content || []).map(c => c.text || '').join('');
let d = { type: 'other' };
try { d = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1)); } catch (e) {}
if (d.guest_phone) d.guest_phone = String(d.guest_phone).replace(/\D/g, '');
if (d.guest_phone && d.guest_phone.length === 10) d.guest_phone = '91' + d.guest_phone;
return [{ json: d }];

const C = $('Config').first().json.CONFIG;
const url = C.WA_API + '/' + C.WA_PHONE_NUMBER_ID + '/messages';
const b = $input.first().json;
const meetText = t => ({ json: { kind: 'whatsapp', url, body: { messaging_product: 'whatsapp', to: C.MEET_WHATSAPP, type: 'text', text: { body: t } } } });
if (!b || !b.id || !b.guest_phone) {
  return [meetText('I could not match that to a booking waiting for a guest number. Please send the confirmation code with the guest name and WhatsApp number.')];
}
const first = String(b.guest_name || b.guest_first_name || 'there').split(' ')[0];
const day = b.check_in ? new Date(b.check_in).toLocaleDateString('en-IN', { weekday: 'short', day: 'numeric', month: 'short', timeZone: 'Asia/Kolkata' }) : 'your arrival day';
return [
  { json: { kind: 'whatsapp', url, body: {
    messaging_product: 'whatsapp', to: b.guest_phone, type: 'template',
    template: { name: 'tes_booking_welcome', language: { code: 'en' }, components: [{ type: 'body', parameters: [
      { type: 'text', text: first }, { type: 'text', text: b.listing_name || 'your stay' }, { type: 'text', text: day }
    ] }] }
  } } },
  { json: { kind: 'db', sql: "INSERT INTO airsynk.messages (phone, direction, body) VALUES ($1, 'out', $2)", params: [b.guest_phone, '[template tes_booking_welcome] ' + first + ' · ' + (b.listing_name || '') + ' · ' + day] } },
  meetText('Done. Maya is now looking after ' + first + ' (+' + b.guest_phone + ') for ' + (b.listing_name || 'the booking') + ', check-in ' + day + '. Welcome message sent.'),
  { json: { kind: 'slack', body: { channel: C.SLACK_CHANNEL, text: '01B · Guest contact added · ' + (b.confirmation_code || '') + ' · ' + (b.listing_name || '') + ' · welcome sent on WhatsApp' } } }
];

const C = $('Config').first().json.CONFIG;
const url = C.WA_API + '/' + C.WA_PHONE_NUMBER_ID + '/messages';
const e = $input.first().json;
const meetText = t => ({ json: { kind: 'whatsapp', url, body: { messaging_product: 'whatsapp', to: C.MEET_WHATSAPP, type: 'text', text: { body: t } } } });
if (!e || !e.id) return [meetText('Nothing is waiting for your decision right now.')];
if (!e.final_reply) return [meetText('Okay, holding it. Nothing was sent to the guest.'), { json: { kind: 'slack', body: { channel: C.SLACK_CHANNEL, text: '01B · ' + e.id + ' held by Meet' } } }];
return [
  { json: { kind: 'whatsapp', url, body: { messaging_product: 'whatsapp', to: e.phone, type: 'text', text: { body: e.final_reply } } } },
  { json: { kind: 'db', sql: "INSERT INTO airsynk.messages (phone, direction, body) VALUES ($1, 'out', $2)", params: [e.phone, e.final_reply] } },
  meetText('Sent to the guest: "' + e.final_reply.slice(0, 300) + '"'),
  { json: { kind: 'slack', body: { channel: C.SLACK_CHANNEL, text: '01B · ' + e.id + ' ' + e.resolution + ' by Meet → sent' } } }
];

const C = $('Config').first().json.CONFIG;
const msg = $('Read message').first().json;
const row = $input.first().json;
if (Number(row.inserted) === 0) return []; // Meta retried a message we already handled
const b = row.booking || {};
const SYSTEM = `You are Maya, the guest host of The Empire Stays: premium serviced apartments in Mumbai (Goregaon East) and Thane (near Korum Mall, TheWalk, Hiranandani, G-Corp). You talk to guests on WhatsApp.

Voice: Ritz-Carlton Gold Standard. Warm, human, anticipatory, never robotic. English only. Use the guest's first name. Short WhatsApp-sized messages, no emoji walls, no markdown.

Facts you may rely on:
- Check-in from 2:00 PM. Early check-in from 12:30 PM only if the guest asks, subject to the turnover being ready.
- Check-out by 11:00 AM. Never agree to anything later than 11:30 AM.
- Discounts you may offer yourself: same-day booking 5%, 7–13 nights 7%, 14–27 nights 10%, 28+ nights 15%. Anything else: say you will check with the team.
- Share the exact address only when a confirmed booking is on file below.
- Use only the property details given below. If a detail is missing, say you will confirm it shortly. Never invent Wi-Fi passwords, codes or addresses.
- Emergencies: police 100, ambulance 108, all emergencies 112.

Never answer these yourself; set escalate=true: refund requests, payment disputes, legal threats, injury or safety issues, commercial shoots or events, discounts beyond the tiers, anything suspicious, complaints about cleanliness or broken essentials (AC, water, power, lock), and any guest who is angry.
Urgency: critical = safety, emergency, guest locked out, no water/power at night; urgent = complaint during the stay, refund, checkout breach, angry guest; normal = needs Meet but can wait; none = routine.

Reply with ONE JSON object only:
{"reply": string|null, "holding_reply": string|null, "intent": "faq"|"checkin"|"checkout"|"amenity"|"directions"|"early_checkin"|"late_checkout"|"discount"|"complaint"|"refund"|"payment_dispute"|"legal"|"emergency"|"commercial"|"suspicious"|"other", "escalate": boolean, "urgency": "none"|"normal"|"urgent"|"critical", "summary_for_meet": string}
reply = the message you would send (also when escalating, as your suggested draft for Meet). holding_reply = a short, warm line to send now while the team checks (null for refund, payment_dispute, legal, commercial, suspicious). summary_for_meet = one or two plain sentences.`;
const ctx = b.id ? [
  'Booking on file: ' + (b.listing_name || '?') + ' (' + (b.listing_code || '?') + '), ' + (b.check_in || '?') + ' → ' + (b.check_out || '?') + ', ' + (b.guests || '?') + ' guests, status ' + b.status + ', code ' + (b.confirmation_code || '?') + '.',
  'Guest name: ' + (b.guest_name || b.guest_first_name || msg.name || 'unknown') + '.',
  'Address: ' + (b.address || 'not on file') + '. Wi-Fi: ' + (b.wifi_name ? b.wifi_name + ' / ' + (b.wifi_password || '?') : 'not on file') + '.',
  'Check-in guide: ' + (b.checkin_guide || 'not on file') + '. House rules: ' + (b.house_rules || 'not on file') + '.'
].join('\n') : 'No confirmed booking matches this number. Treat as an inquiry: be helpful, do not share any address, and invite them to book on Airbnb.';
const hist = (row.history || []).map(h => (h.direction === 'in' ? 'Guest: ' : 'Maya: ') + h.body).join('\n');
const user = ctx + '\n\nConversation so far:\n' + (hist || '(none)') + '\n\nNew WhatsApp message from ' + (msg.name || 'the guest') + ': ' + msg.text;
return [{ json: { from: msg.from, name: msg.name, text: msg.text, booking: b, claudeRequest: { model: C.MODEL_BRAIN, max_tokens: 900, system: SYSTEM, messages: [{ role: 'user', content: user }] } } }];

const C = $('Config').first().json.CONFIG;
const ctx = $('Prepare Maya').first().json;
const url = C.WA_API + '/' + C.WA_PHONE_NUMBER_ID + '/messages';
const txt = ($input.first().json.content || []).map(c => c.text || '').join('');
let d;
try { d = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1)); }
catch (e) { d = { reply: null, holding_reply: null, intent: 'other', escalate: true, urgency: 'normal', summary_for_meet: 'Maya could not read this message: ' + ctx.text }; }
const NO_REPLY = ['refund', 'payment_dispute', 'legal', 'commercial', 'suspicious'];
const urgency = d.urgency || 'none';
const escalate = !!d.escalate || NO_REPLY.includes(d.intent) || urgency === 'urgent' || urgency === 'critical';
const b = ctx.booking || {};
const guest = (b.guest_name || b.guest_first_name || ctx.name || ('+' + ctx.from));
const label = guest + ' · ' + (b.listing_name || 'no booking on file');
const out = [];
const waText = (to, body) => ({ json: { kind: 'whatsapp', url, body: { messaging_product: 'whatsapp', to, type: 'text', text: { body } } } });
const logOut = body => ({ json: { kind: 'db', sql: "INSERT INTO airsynk.messages (phone, direction, body) VALUES ($1, 'out', $2)", params: [ctx.from, body] } });

// 1. What the guest gets right now
let guestText = null;
if (!escalate && d.reply && C.AUTO_SEND) guestText = d.reply;
else if (d.intent === 'emergency') guestText = d.reply || 'Please call 112 right away if anyone is in danger. I am alerting our team this minute and we will call you back.';
else if (escalate && !NO_REPLY.includes(d.intent) && d.holding_reply) guestText = d.holding_reply;
if (guestText) { out.push(waText(ctx.from, guestText)); out.push(logOut(guestText)); }

// 2. What Meet gets: every escalation, and every draft while AUTO_SEND is off
const needsMeet = escalate || (!C.AUTO_SEND && d.reply);
const escId = 'esc_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
if (needsMeet) {
  out.push({ json: { kind: 'db', sql: 'INSERT INTO airsynk.escalations (id, phone, booking_id, intent, urgency, summary, draft_reply) VALUES ($1, $2, NULLIF($3, \'\')::bigint, $4, $5, $6, $7)', params: [escId, ctx.from, b.id ? String(b.id) : '', d.intent || 'other', urgency, d.summary_for_meet || ctx.text, d.reply || ''] } });
  out.push({ json: { kind: 'whatsapp', url, body: {
    messaging_product: 'whatsapp', to: C.MEET_WHATSAPP, type: 'template',
    template: { name: 'tes_meet_alert', language: { code: 'en' }, components: [{ type: 'body', parameters: [
      { type: 'text', text: escalate ? urgency.toUpperCase() : 'DRAFT' },
      { type: 'text', text: label.slice(0, 120) },
      { type: 'text', text: (d.summary_for_meet || ctx.text).slice(0, 600) },
      { type: 'text', text: (d.reply || 'No reply drafted: policy says you decide.').slice(0, 600) }
    ] }] }
  } } });
}

// 3. Jarvis phones Meet for urgent and critical items
if (escalate && (urgency === 'urgent' || urgency === 'critical')) {
  const x = s => String(s || '').replace(/[<>&"']/g, ' ');
  const say = 'Hey Meet, this is Jarvis. ' + x(urgency) + ' item from ' + x(label) + '. ' + x(d.summary_for_meet) + (d.reply ? ' Maya suggests replying: ' + x(d.reply) + '.' : '') + ' Say approve to send it, hold to wait, or tell me what to say.';
  const twiml = '<Response><Gather input="speech" language="en-IN" speechTimeout="auto" method="POST" action="' + C.N8N_PUBLIC_URL + '/webhook/tes-voice?esc=' + escId + '"><Say voice="Polly.Raveena" language="en-IN">' + say + '</Say></Gather><Say voice="Polly.Raveena" language="en-IN">I did not catch that. The details are on your WhatsApp.</Say></Response>';
  out.push({ json: { kind: 'call', accountSid: C.TWILIO_ACCOUNT_SID, to: C.MEET_PHONE_E164, from: C.TWILIO_FROM, twiml } });
}

out.push({ json: { kind: 'slack', body: { channel: C.SLACK_CHANNEL, text: '01B · ' + label + ' · intent ' + (d.intent || '?') + ' · urgency ' + urgency + (escalate ? ' · ESCALATED ' + escId : (guestText ? ' · Maya replied' : ' · draft to Meet')) } } });
return out;
